export interface TabInfo {
  id: number;
  windowId: number;
  index: number;
  active: boolean;
  title: string;
  url: string;
}

export interface BrowserAdapter {
  getCurrentWindowId(): Promise<number>;
  getCurrentTabId(): Promise<number | undefined>;
  listTabs(scope: 'all' | 'current'): Promise<TabInfo[]>;
  activateTab(tabId: number): Promise<'activated' | 'not_found'>;
  openUrl(url: string): Promise<void>;
  search(query: string): Promise<void>;
  loadHistory(): Promise<string[]>;
  saveHistory(entries: string[]): Promise<void>;
  onHistoryChanged(listener: (entries: string[]) => void): () => void;
}

export interface CompletionItem {
  value: string;
  label?: string;
}

export interface CommandContext {
  adapter: BrowserAdapter;
  registry: CommandRegistry;
  cols: number;
  write(text: string): void;
  writeln(text?: string): void;
  clear(): void;
}

export interface CommandDefinition {
  name: string;
  summary: string;
  usage: string;
  execute(ctx: CommandContext, args: string[]): Promise<void> | void;
  complete?(ctx: CommandContext, args: string[], currentToken: string): Promise<CompletionItem[]> | CompletionItem[];
}
